/* Point geometry and directed force lesson. All views use actual 3D coordinates. */
(() => {
 const axes=['x','y','z'],precise=n=>Math.abs(n)<.0000005?'0':Number(n.toFixed(4)).toString();
 const num=n=>'<mn>'+precise(n)+'</mn>',text=s=>'<mtext>'+s+'</mtext>',tuple=values=>'('+values.map(precise).join(', ')+')';
 const expansion=(values,unit='')=>values.map((v,i)=>(i?mo('+'):'')+mo('(')+num(v)+mo(')')+mi(['i','j','k'][i])).join('')+(unit?text(' '+unit):'');
 const square=v=>'<msup><mrow>'+v+'</mrow><mn>2</mn></msup>',root=v=>'<msqrt><mrow>'+v+'</mrow></msqrt>';
 let geometry={A:[1,1,0],B:[4,5,0],force:100,reverse:false,view:'xy'};
 const container=$('position');
 container.innerHTML=`<div class="lesson-strip"><span class="number">02</span><div><h2>From two points to a force vector</h2><p>Displacement → distance → unit direction → force components.</p></div><button id="positionReset">Reset geometry</button></div>
 <div class="lab-grid"><article class="panel"><div class="panel-heading"><h3>Point & cable lab</h3><span class="live">● LIVE GEOMETRY</span></div>
 <p id="geometryProblem" class="position-problem"></p>
 <div class="projection-choices" role="group" aria-label="Diagram projection"><button data-projection="xy" aria-pressed="true">xy view</button><button data-projection="xz" aria-pressed="false">xz view</button><button data-projection="yz" aria-pressed="false">yz view</button><button data-projection="iso" aria-pressed="false">3D projection</button></div>
 <svg id="positionDiagram" viewBox="0 0 600 400" role="img" aria-label="Points A and B and their directed displacement"></svg><p id="projectionHelp" class="diagram-help"></p>
 <div class="coordinate-controls">${['A','B'].map(point=>`<fieldset><legend>Point ${point} · coordinates in m</legend><div class="coordinate-row">${axes.map((axis,i)=>`<label>${axis}<input id="point${point}${i}" type="number" step="any" min="-10000" max="10000" value="${geometry[point][i]}"></label>`).join('')}</div></fieldset>`).join('')}</div>
 <label class="force-input">Force magnitude F (N)<input id="pointForce" type="number" min="0" max="100000" step="any" value="100"></label>
 <div class="actions"><button id="reverseDirection">Reverse: A→B / B→A</button><button id="example3D">Try a 3D example</button></div>
 <p id="positionError" class="error" role="status"></p><div id="positionSummary" class="result-summary" aria-live="polite"></div></article>
 <article class="panel"><div class="panel-heading"><h3>Geometry, step by step</h3><span class="badge">m → UNITLESS → N</span></div><div class="symbol-help">Tap an <strong>underlined symbol</strong> for its meaning in this equation. Calculations use full precision; values display up to 4 decimals.</div><div id="positionSteps"></div></article></div>
 <article class="panel concept"><h3>Position, displacement, and unit direction are different quantities.</h3><div class="concept-grid"><p><strong>Position is measured from the origin.</strong><br>rA locates A; rB locates B. Translating both points together changes their positions but leaves their displacement unchanged.</p><p><strong>Displacement goes from start to end.</strong><br>rAB = rB − rA. Reversing the direction negates the vector while preserving its length.</p><p><strong>A unit vector removes the length.</strong><br>Divide each displacement component by the same distance. Its magnitude is <strong>1</strong>; its components have <strong>no units</strong>.</p></div></article>
 <article class="panel position-practice"><div class="eyebrow">GUIDED PRACTICE / POINTS TO FORCE</div><h2>Can you build the direction yourself?</h2><p id="positionPracticeProblem" class="position-problem"></p><div id="positionPracticeInputs"></div><div class="actions"><button id="positionCheck" class="primary">Check current step</button><button id="positionHint">Show a hint</button><button id="positionReveal">Show worked solution</button><button id="positionNew">New problem</button></div><p id="positionFeedback" role="status"></p><p id="positionHintText"></p><div id="positionPracticeSolution" hidden></div></article>`;
 function steps(g){
  const start=g.reverse?g.B:g.A,end=g.reverse?g.A:g.B,result=M.directedForce(start,end,g.force),suffix=g.reverse?'BA':'AB',dkey=g.reverse?'displacementBA':'displacement',ukey=g.reverse?'unitBA':'unitAB',startLabel=g.reverse?'B':'A',endLabel=g.reverse?'A':'B';
  const rv=taggedVector('r',suffix,dkey),uv=taggedVector('u',suffix,ukey),length=symbolMarkup('|r'+suffix+'|','lengthAB','<mrow><mo>|</mo><msub><mi>r</mi><mtext>'+suffix+'</mtext></msub><mo>|</mo></mrow>');
  let output=`<div class="step" data-equation="Displacement from ${startLabel} to ${endLabel}"><div class="step-title"><span>01</span> End minus start</div><div class="math">${math(rv+mo('=')+taggedVector('r',endLabel,'position'+endLabel)+mo('−')+taggedVector('r',startLabel,'position'+startLabel))}${axes.map((axis,i)=>math(sub('r',axis)+mo('=')+mo('(')+num(end[i])+mo(')')+mo('−')+mo('(')+num(start[i])+mo(')')+mo('=')+num(result.displacement[i])+text(' m'))).join('')}${math(rv+mo('=')+expansion(result.displacement,'m'))}</div><p><strong>Need:</strong> both points’ coordinates from the <strong>same origin and in the same units</strong>. For ${startLabel}→${endLabel}, subtract <strong>${endLabel} − ${startLabel}</strong>.</p></div>`;
  output+=`<div class="step" data-equation="Distance between the points"><div class="step-title"><span>02</span> Calculate the length</div><div class="math">${math(length+mo('=')+root(axes.map((axis,i)=>(i?mo('+'):'')+square(sub('r',axis))).join('')))}${math(length+mo('=')+root(result.displacement.map((v,i)=>(i?mo('+'):'')+square(mo('(')+num(v)+mo(')'))).join(''))+mo('=')+num(result.length)+text(' m'))}</div><p>Use <strong>perpendicular Cartesian axes</strong>. The distance is nonnegative and is <strong>unchanged when direction reverses</strong>.</p></div>`;
  if(!result.unit)return output+'<div class="insight"><strong>A and B coincide: direction is undefined.</strong><p>The displacement and distance are <strong>zero</strong>. Dividing by zero cannot produce a unit vector. Move one point before calculating a directed force.</p></div>';
  output+=`<div class="step" data-equation="Unit direction from ${startLabel} to ${endLabel}"><div class="step-title"><span>03</span> Divide by the length</div><div class="math">${math(uv+mo('=')+fraction(rv,length))}${axes.map((axis,i)=>math(sub('u',axis)+mo('=')+fraction(num(result.displacement[i]),num(result.length))+mo('=')+num(result.unit[i]))).join('')}${math(uv+mo('=')+expansion(result.unit))}</div><p><strong>Condition:</strong> distance &gt; 0. The metre units cancel. Every component uses the <strong>same length denominator</strong>.</p><div class="unit-check">Check: |u| = √(${result.unit.map(v=>'('+precise(v)+')²').join(' + ')}) ≈ <strong>${precise(Math.hypot(...result.unit))}</strong> · dimensionless</div></div>`;
  output+=`<div class="step" data-equation="Force along ${startLabel} to ${endLabel}"><div class="step-title"><span>04</span> Multiply by force magnitude</div><div class="math">${math(vector('F','Fvector')+mo('=')+mi('F')+uv)}${axes.map((axis,i)=>math(sub('F',axis)+mo('=')+num(g.force)+mo('×')+mo('(')+num(result.unit[i])+mo(')')+mo('=')+num(result.force[i])+text(' N'))).join('')}${math(vector('F','Fvector')+mo('=')+expansion(result.force,'N'))}</div><p><strong>Need:</strong> a <strong>force magnitude of ${fmt(g.force)} N</strong> and a unit vector in the <strong>actual pull direction</strong>. The force components have <strong>newton units</strong>. ${g.force===0?'<strong>With zero force, the force direction is undefined</strong>; the geometric unit direction still exists.':''}</p></div>`;
  output+=`<details class="direction-details"><summary>Explore the 3D coordinate direction angles</summary><div class="step" data-equation="3D coordinate direction angles of the displacement"><p>These are the angles between <strong>the displacement and each positive axis</strong>, from <strong>0° to 180°</strong>. They differ from the planar angles in the force lab.</p><div class="math">${axes.map((axis,i)=>math(mi(['α','β','γ'][i],['alpha3D','beta3D','gamma3D'][i])+mo('=')+'<msup><mi>cos</mi><mn>−1</mn></msup>'+mo('(')+sub('u',axis)+mo(')')+mo('=')+num(result.angles[i])+mo('°'))).join('')}</div><p><strong>Check:</strong> cos²α + cos²β + cos²γ = 1. A negative component gives an angle greater than 90° with its positive axis.</p></div></details>`;
  return output;
 }
 let projectionData,drag=null;
 function draw(g){
  const svg=$('positionDiagram'),pair={xy:[0,1],xz:[0,2],yz:[1,2]}[g.view],project=point=>pair?[point[pair[0]],point[pair[1]]]:[.866*(point[0]-point[1]),point[2]-.5*(point[0]+point[1])];
  const fitExtent=Math.max(1,...g.A.map(Math.abs),...g.B.map(Math.abs))*1.2,frame=GraphScales.frame('positionDiagram',g.view,{scale:140/(fitExtent*(pair?1:1.732)),offsetX:300,offsetY:200,extent:fitExtent},()=>draw(g),'m'),{scale,offsetX,offsetY,extent}=frame;
  const screen=point=>{const q=project(point);return [offsetX+q[0]*scale,offsetY-q[1]*scale];},A=screen(g.A),B=screen(g.B),O=screen([0,0,0]);
  projectionData={pair,scale,offsetX,offsetY};let out='<defs><marker id="pointArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#b4f178"/></marker></defs>';
  out+='<rect width="600" height="400" fill="#141b24"/>';
  out+=GraphScales.axesSVG(g.view,screen,extent,'m');
  const physicalStart=g.reverse?g.B:g.A,physicalEnd=g.reverse?g.A:g.B,displacement=physicalEnd.map((v,i)=>v-physicalStart[i]);if(Math.hypot(...displacement)>0){for(let i=0;i<3;i++){const axis=[0,0,0];axis[i]=1;out+=GraphScales.spatialAngle(screen,physicalStart,axis,displacement,(25+i*14)/scale,['α: +x to r','β: +y to r','γ: +z to r'][i],['#8cbcff','#efbd77','#d3a0ee'][i]);}out+='<text x="12" y="390" font-size="11" fill="#b9c7d8">α, β, γ are true 3D direction angles; arcs are projected.</text>';}
  const start=g.reverse?B:A,end=g.reverse?A:B;out+=`<line x1="${start[0]}" y1="${start[1]}" x2="${end[0]}" y2="${end[1]}" stroke="#b4f178" stroke-width="3" marker-end="url(#pointArrow)"/>`;
  for(const [label,point,c] of [['A',A,'#8cbcff'],['B',B,'#efbd77']])out+=`<circle data-point="${label}" cx="${point[0]}" cy="${point[1]}" r="15" fill="${c}" fill-opacity=".2" stroke="${c}" style="cursor:${pair?'grab':'default'}"/><circle cx="${point[0]}" cy="${point[1]}" r="4" fill="${c}" pointer-events="none"/><text x="${point[0]+18}" y="${point[1]-14}" fill="${c}">${label}</text>`;
  const axisHidden=pair?axes[[0,1,2].find(i=>!pair.includes(i))]:null;GraphScales.paint(svg,out);$('projectionHelp').textContent=pair?`Drag A or B to edit the ${axes[pair[0]]} and ${axes[pair[1]]} coordinates; ${axisHidden} stays fixed. This is a projection: the visible length may differ from the actual 3D distance. The cable arrow is displacement (m); force magnitude F affects calculations only.`:'Projected 3D view; edit coordinates below or use an axis view to drag points. Screen angles and lengths are not physical measurements. The cable arrow shows displacement in metres, not force magnitude; changing F changes the force calculations, not this geometry.';
 }
 function renderPosition(){
  const start=geometry.reverse?'B':'A',end=geometry.reverse?'A':'B',result=M.directedForce(geometry[start],geometry[end],geometry.force);
  $('geometryProblem').innerHTML=`Point <strong class="f1">A = ${tuple(geometry.A)} m</strong> and point <strong class="f2">B = ${tuple(geometry.B)} m</strong>. A cable exerts <strong>${fmt(geometry.force)} N</strong> at <strong>${start}</strong>, pulling <strong>toward ${end}</strong>. Find its Cartesian force vector.`;
  $('positionSteps').innerHTML=steps(geometry);draw(geometry);
  $('positionSummary').innerHTML=`<div><small>POINT-TO-POINT DISTANCE</small>${precise(result.length)} m</div><div><small>DIRECTION</small>${start} → ${end}</div>`;
  $('positionError').textContent=result.unit?'':'A and B coincide. A unit vector and directed force cannot be calculated.';
  document.querySelectorAll('[data-projection]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.projection===geometry.view)));
 }
 function sync(){for(const point of ['A','B'])geometry[point].forEach((v,i)=>$('point'+point+i).value=v);$('pointForce').value=geometry.force;}
 function inputChange(){
  const values=['A','B'].map(point=>axes.map((_,i)=>$('point'+point+i).value)),forceValue=$('pointForce').value,flat=[...values.flat(),forceValue];
  if(flat.some(v=>v.trim()===''||!Number.isFinite(Number(v)))){$('positionError').textContent='Enter a finite number for every coordinate and the force magnitude.';return;}
  if(values.flat().some(v=>Math.abs(Number(v))>10000)||Number(forceValue)<0||Number(forceValue)>100000){$('positionError').textContent='Coordinates must be between −10,000 and 10,000 m; force must be between 0 and 100,000 N.';return;}
  geometry.A=values[0].map(Number);geometry.B=values[1].map(Number);geometry.force=Number(forceValue);renderPosition();
 }
 for(const point of ['A','B'])axes.forEach((_,i)=>$('point'+point+i).addEventListener('input',inputChange));$('pointForce').addEventListener('input',inputChange);
 document.querySelectorAll('[data-projection]').forEach(button=>button.onclick=()=>{geometry.view=button.dataset.projection;drag=null;renderPosition();});
 $('reverseDirection').onclick=()=>{geometry.reverse=!geometry.reverse;renderPosition();};$('positionReset').onclick=()=>{geometry={A:[1,1,0],B:[4,5,0],force:100,reverse:false,view:'xy'};sync();renderPosition();};$('example3D').onclick=()=>{geometry={A:[1,2,3],B:[-1,5,9],force:350,reverse:false,view:'iso'};sync();renderPosition();};
 $('positionDiagram').onpointerdown=e=>{const point=e.target.dataset.point;if(!point||!projectionData.pair)return;drag={point,...projectionData};$('positionDiagram').setPointerCapture(e.pointerId);};
 $('positionDiagram').onpointermove=e=>{if(!drag)return;let p=$('positionDiagram').createSVGPoint();p.x=e.clientX;p.y=e.clientY;p=p.matrixTransform($('positionDiagram').getScreenCTM().inverse());const coordinates=[(p.x-drag.offsetX)/drag.scale,(drag.offsetY-p.y)/drag.scale];drag.pair.forEach((axis,i)=>geometry[drag.point][axis]=Math.max(-10000,Math.min(10000,Number(coordinates[i].toFixed(2)))));sync();renderPosition();};
 $('positionDiagram').onpointerup=$('positionDiagram').onpointercancel=()=>drag=null;
 let exercise={A:[2,1,0],B:[5,5,0],force:200,reverse:false},stage=0,hintCount=0;
 function renderExercise(){
  $('positionPracticeProblem').innerHTML=`A cable pulls at <strong>A = ${tuple(exercise.A)} m</strong> toward <strong>B = ${tuple(exercise.B)} m</strong> with magnitude <strong>${exercise.force} N</strong>. Work through the displacement, unit vector, and force components.`;
  const fields=stage===0?[['rx','rₓ (m)'],['ry','rᵧ (m)'],['rz','r_z (m)']]:stage===1?[['length','Distance (m)'],['ux','uₓ (unitless)'],['uy','uᵧ (unitless)'],['uz','u_z (unitless)']]:[['fx','Fₓ (N)'],['fy','Fᵧ (N)'],['fz','F_z (N)']];
  $('positionPracticeInputs').innerHTML=`<h3>Step ${stage+1} / ${['End minus start','Distance and unit direction','Force components'][stage]}</h3><div class="position-answer-grid">${fields.map(([id,label])=>`<label>${label}<input id="positionAnswer${id}" type="number" step="any"></label>`).join('')}</div>`;
  $('positionCheck').disabled=false;$('positionFeedback').textContent='';$('positionHintText').textContent='';hintCount=0;
 }
 $('positionCheck').onclick=()=>{
  const result=M.directedForce(exercise.A,exercise.B,exercise.force),keys=stage===0?['rx','ry','rz']:stage===1?['length','ux','uy','uz']:['fx','fy','fz'],expected=stage===0?result.displacement:stage===1?[result.length,...result.unit]:result.force,values=keys.map(key=>$('positionAnswer'+key).value);
  if(values.some(v=>v.trim()===''||!Number.isFinite(Number(v)))){$('positionFeedback').textContent='Fill in every component for this step, including zero components.';return;}
  const correct=values.every((v,i)=>Math.abs(Number(v)-expected[i])<=(stage===0?.01:stage===1?(i===0?.01:.005):.1));
  if(correct&&stage<2){stage++;renderExercise();$('positionFeedback').textContent='Correct. Continue with the next step.';}
  else if(correct){$('positionFeedback').textContent='Correct. You built the force from geometry. Its magnitude equals the given cable force.';$('positionCheck').disabled=true;}
  else if(stage===0&&values.every((v,i)=>Math.abs(Number(v)+expected[i])<=.01))$('positionFeedback').textContent='Your signs indicate B→A. The cable here pulls at A toward B, so subtract B − A.';
  else $('positionFeedback').textContent=stage===0?'Check each coordinate: ending point B minus starting point A.':stage===1?'Use the full 3D distance as the common denominator. Unit-vector components have no units. Tolerances: 0.01 m and 0.005 per unit component.':'Multiply each unit-vector component by the force magnitude. Keep its sign. Answers within 0.1 N are accepted.';
 };
 $('positionHint').onclick=()=>{const result=M.directedForce(exercise.A,exercise.B,exercise.force),hints=[['The arrow points A→B. Write rAB = rB − rA before inserting numbers.',`For x, subtract (${exercise.B[0]}) − (${exercise.A[0]}). Repeat for y and z.`],['Find the distance from all three displacement components using the Pythagorean theorem.',`Divide each displacement component by ${precise(result.length)} m. Do not divide by a coordinate of B alone.`],['A unit vector gives direction only. The given force magnitude supplies the newton units.',`Use Fₓ = ${exercise.force} × uₓ; repeat for y and z.`]];$('positionHintText').textContent=hints[stage][Math.min(hintCount++,1)];};
 $('positionReveal').onclick=()=>{$('positionPracticeSolution').innerHTML=steps(exercise);$('positionPracticeSolution').hidden=false;};
 $('positionNew').onclick=()=>{const examples=[{A:[1,2,3],B:[-1,5,9],force:350},{A:[-2,3,1],B:[1,-1,1],force:150},{A:[0,0,2],B:[0,0,-3],force:250},{A:[2,-1,0],B:[5,3,12],force:130}];exercise={...examples[Math.floor(Math.random()*examples.length)],reverse:false};stage=0;$('positionPracticeSolution').hidden=true;renderExercise();};
 renderPosition();renderExercise();
})();
